int speakerPin = 8;

int melody[] = { 262, 294, 330, 349, 392, 440, 494, 523 };
int noteDurations[] = { 200, 200, 200, 200, 200, 200, 200, 400 };

void setup() {
  for (int i = 0; i < 8; i++) {
    tone(speakerPin, melody[i], noteDurations[i]);
    delay(noteDurations[i] + 50);
    noTone(speakerPin);
  }
  delay(1000);
}
void loop() {
  setup();
  while(1);
}
